html='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>레콘키스타 · 한글 오프닝</title><style>
*{box-sizing:border-box}body{margin:0;background:#111119;color:#e9e6ee;font:16px system-ui,sans-serif;padding:28px}h1{font-size:24px;font-weight:650;margin:0 0 8px}p{color:#aaa7b6;margin:8px 0 20px}button,select,a.link{font:inherit;color:inherit;background:#282633;border:1px solid #555164;border-radius:7px;padding:9px 14px;text-decoration:none}button{cursor:pointer}nav{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:20px 0}#zoom{min-width:60px;color:#d9c3f8}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}figure{margin:0;border:1px solid #45404e;border-radius:10px;overflow:hidden;background:#09090d}figcaption{padding:10px 16px;background:#1d1b25;display:flex;justify-content:space-between;color:#c6bccc}.stage{height:58vh;min-height:350px;position:relative;overflow:hidden;cursor:grab;touch-action:none;background:radial-gradient(#22212b,#08080d)}.stage.dragging{cursor:grabbing}.stage img{position:absolute;left:0;top:0;max-width:none;user-select:none;pointer-events:none;transform-origin:0 0}video{display:block;width:min(100%,1200px);margin:24px auto;background:#000;border-radius:10px}section{margin-top:34px}footer{margin:30px 0 60px;color:#9e96a9;line-height:1.8}@media(max-width:850px){body{padding:16px}.grid{grid-template-columns:1fr}.stage{height:50vh}}
</style><h1>레콘키스타 · 한글 오프닝</h1><p>게임용 화면과 16:9 4K 리마스터를 나란히 확인하세요.</p><nav><select id="frames" aria-label="검토 장면"></select><button id="fit">화면에 맞춤</button><output id="zoom">100%</output><a class="link" href="../viewing/Reconquista_OP_KO_4K.mp4">4K 영상 열기</a><a class="link" href="../payloads/movie/Recon_OP800_H.mpg">게임용 MPEG</a></nav><p>이미지 위에서 휠로 확대·축소, 드래그로 이동합니다. 더블클릭하면 화면에 맞춥니다. 두 화면은 함께 움직입니다.</p><div class="grid"><figure><figcaption>게임용 <small>800 × 600</small></figcaption><div class="stage" id="sd"><img alt="게임용 검토 프레임" draggable="false"></div></figure><figure><figcaption>4K 리마스터 <small>3840 × 2160</small></figcaption><div class="stage" id="uhd"><img alt="4K 검토 프레임" draggable="false"></div></figure></div><section><h1>4K 영상</h1><video controls preload="metadata" src="../viewing/Reconquista_OP_KO_4K.mp4"></video></section><footer>을유1945 명조 계열 자막 · 원본 디자인을 살린 한글 로고<br>4K판은 원본 영상을 복원·업스케일하고 한글을 고해상도로 합성한 감상용 파일입니다.<br>게임용 영상은 원본 MP2 음원을 보존합니다.</footer><script>
const frames=__FRAMES__;const panes=[...document.querySelectorAll('.stage')];const picker=document.querySelector('#frames');let state={z:1,cx:.5,cy:.5};let drag=null;
for(const [i,f] of frames.entries()){const o=document.createElement('option');o.value=i;o.textContent=`${f.time.toFixed(2)}초 · 프레임 ${f.n}`;picker.append(o)}
function geometry(el){const img=el.querySelector('img'),r=el.getBoundingClientRect(),f=Math.min(r.width/(img.naturalWidth||1),r.height/(img.naturalHeight||1));return {r,img,f,w:img.naturalWidth*f,h:img.naturalHeight*f}}
function render(){for(const el of panes){const g=geometry(el);if(!g.img.naturalWidth)continue;g.img.style.width=g.img.naturalWidth+'px';g.img.style.height=g.img.naturalHeight+'px';const x=g.r.width/2-state.cx*g.w*state.z,y=g.r.height/2-state.cy*g.h*state.z;g.img.style.transform=`translate(${x}px,${y}px) scale(${g.f*state.z})`;el.dataset.zoom=state.z.toFixed(5)}document.querySelector('#zoom').value=Math.round(state.z*100)+'%';window.reviewZoom={...state}}
function fit(){state={z:1,cx:.5,cy:.5};render()}
function show(){const f=frames[+picker.value];for(const el of panes){const img=el.querySelector('img');img.onload=render;img.src=f[el.id]}fit()}
for(const el of panes){el.addEventListener('wheel',e=>{if(e.ctrlKey||e.metaKey)return;e.preventDefault();const g=geometry(el),mx=e.clientX-g.r.left-g.r.width/2,my=e.clientY-g.r.top-g.r.height/2;const qx=state.cx+mx/(g.w*state.z),qy=state.cy+my/(g.h*state.z);state.z=Math.max(.5,Math.min(16,state.z*Math.exp(-e.deltaY*.0015)));state.cx=qx-mx/(g.w*state.z);state.cy=qy-my/(g.h*state.z);render()},{passive:false});el.addEventListener('dblclick',fit);el.addEventListener('pointerdown',e=>{if(e.button!==0)return;drag={el,x:e.clientX,y:e.clientY,cx:state.cx,cy:state.cy};el.classList.add('dragging');el.setPointerCapture(e.pointerId)});el.addEventListener('pointermove',e=>{if(!drag||drag.el!==el)return;const g=geometry(el);state.cx=drag.cx-(e.clientX-drag.x)/(g.w*state.z);state.cy=drag.cy-(e.clientY-drag.y)/(g.h*state.z);render()});el.addEventListener('pointerup',()=>{drag=null;el.classList.remove('dragging')})}
picker.addEventListener('change',show);document.querySelector('#fit').addEventListener('click',fit);new ResizeObserver(render).observe(document.querySelector('.grid'));show();
</script></html>'''.replace('__FRAMES__',json.dumps(items,ensure_ascii=False))
